}

function transcriptMetrics(host, bytes) {
  let toolCalls = 0;
  let inputTokens = null;
  let outputTokens = null;
  for (const line of bytes.toString("utf8").split(/\r?\n/u)) {
    if (!line) continue;
    let event;
    try { event = JSON.parse(line); } catch { continue; }
    if (host === "codex" && event.type === "item.completed" && ["command_execution", "file_change", "mcp_tool_call"].includes(event.item?.type)) toolCalls += 1;
    if (host === "codex" && event.type === "turn.completed") {
